//! **G_FLEX_SHRINK_IMG_PANE — a `flex: 0 1 auto` pane whose only content is a 100%-sized flex child
//! over a large `<img>` laid out 0 wide in manuk; Chrome gives it the space left by the fixed pane.**
//!
//! Found on the zilloft-2 results page (RG.2.E1.a.a.a.a.a): `row-reverse` flex row, one `flex: 0 0 750px`
//! results pane and a map pane (`flex: 0 1 auto`, content `flex: 1 1 100%` > `width:100%` > `<img
//! width=1920 height=1080>`). Pinned Chrome 145 gives the map pane 530 = 1280 - 750; manuk gave 0.

use manuk_text::FontContext;

const PNG: &str = "";

const HTML_T: &str = r##"<!doctype html><html><head><style>
 body { margin:0 }
 .row { display:flex; flex-direction:row-reverse; min-width:320px; overflow:hidden; height:300px; width:1280px }
 .res { flex:0 0 750px; width:750px; overflow:hidden auto }
 .pane { }
 .inner { overflow:hidden; position:relative; flex:1 1 100%; display:flex; flex-direction:column; height:100% }
 .fill { height:100%; width:100% }
 .fill img { width:100%; height:100%; object-fit:cover }
</style></head><body>
 <div class="row"><div class="res"></div>
  <div class="pane" id="p1"><div class="inner"><div class="fill"><img width="1920" height="1080" src="data:image/png;base64,{PNG}"></div></div></div></div>
 <div id="out">-</div>
 <script>
 window.addEventListener('load', function(){
   document.getElementById('out').textContent = 'p1=' + document.getElementById('p1').offsetWidth;
 });
 </script></body></html>"##;

#[test]
fn a_shrinkable_auto_pane_beside_a_fixed_pane_takes_the_remaining_width() {
    let fonts = FontContext::new();
    let rt = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .unwrap();
    let html = HTML_T.replace("{PNG}", PNG);
    let page = rt.block_on(manuk_page::Page::load_async(
        &html,
        "https://flex.test/",
        &fonts,
        1280.0,
    ));
    let root = page.dom().root();
    let hits = manuk_css::query_selector_all(page.dom(), root, "#out");
    let got = page.dom().text_content(hits[0]);
    println!("FLEX-SHRINK-IMG-PANE {got}");
    assert_eq!(
        got, "p1=530",
        "the map pane is 1280 - 750 wide in Chrome 145"
    );
}
